Class Thermostat
  Private Define degrees As Integer;

  Method Constructor()
    This.degrees <- 20;
  EndMethod

  Method Raise()
    If This.degrees < 30 Then
      This.degrees <- This.degrees + 1;
    EndIf
  EndMethod

  Method Lower()
    If This.degrees > 16 Then
      This.degrees <- This.degrees - 1;
    EndIf
  EndMethod

  Method Degrees() As Integer
    Return This.degrees;
  EndMethod
EndClass

Algorithm Classroom
  Define device As Thermostat <- New Thermostat();
  Define command As String;
  Read command;
  While command <> "end" Do
    If command = "+" Then
      device.Raise();
    Else
      device.Lower();
    EndIf
    Read command;
  EndWhile
  Write device.Degrees();
EndAlgorithm
